 * @tparam T the type of the elements, MUST support emitting to an `ostream` via the `<<` operator
 * @param vec the vector whose element we are emitting
 * @param sep a separator string, by default a newline
 * @return the string resulting from the concatenation of all elements
 */
template<typename T>
inline std::string Vec2Str(const std::vector<T> &vec, const std::string &sep = "\n") {
  bool first = true;
  std::ostringstream out;

  for (auto t : vec) {
    if (!first) out << sep; else first = false;
    out << t;
  }
  return out.str();
}

/**
 * Streams a collection `C`'s contents to `out`, optionally inserting a `coda`.
 */
template <typename C,
          typename T = typename C::value_type>
inline std::ostream& Print(
    const C &items,
    const std::string &coda = "\n",
    const char sep = ',',
    std::ostream& out = std::ref(std::cout)
) {
  out << '[';
  for (const auto &item : items) {
    out << item << sep;
  }
  out << '\b' << ']' << coda;
  return out;
}

